SELECT id, product_name, category, brand, price, cost, stock_qty, launch_date, tags, supplier_id, LAG(stock_qty, 2) OVER (PARTITION BY category ORDER BY launch_date, id) AS prev_stock_qty, RANK() OVER w_grp AS stock_qty_rank, SUM(stock_qty) OVER (PARTITION BY category ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_stock_qty FROM products WINDOW w_grp AS (PARTITION BY brand, supplier_id ORDER BY stock_qty);
